/** POST /duress/{alert}/messages — "Message dispatch…" on the panic screen (board resident-app-06; M50 §4.2 #2): the resident writes to the control room on their OWN open panic. The control room sees it on the alert's page at once and replies there; a reply reaches this phone as the live step `alert.message` (read the alert again) and as an urgent `panic_update` push with `kind` `message`, which no switch and no quiet hours hold. Answers with the alert, `messages` included, exactly as `duress.show` reads it. */
export type DuressMessagesStoreRequest = {
  /** path: {alert} */
  alert: number | string
  /** required · what to say, up to 500 characters kept (longer is cut) */
  body: string
  /** optional · the phone's own id for this message (a UUID). The same key again is the same message, never a second one — send it from the queue as often as the signal needs */
  client_key?: string
  /** Outbox replays only: the Idempotency-Key and device time the act was captured with. */
  __stamp?: import('../write').WriteStamp
}
export type DuressMessagesStoreResponse = {
  /** the alert */
  id: number | string
  /** `duress` from a guard. From a resident: `panic`, or `medical` / `fire` when they chose that `type` — `security`, `other` and no type at all are `panic` */
  kind: string
  /** `silent` or `audible` */
  mode: 'silent' | 'audible'
  /** `open`, `acknowledged`, `responding`, `resolved` or `false_alarm` */
  status: 'open' | 'acknowledged' | 'responding' | 'resolved' | 'false_alarm'
  /** ten seconds after the server received it — UTC instant; show in the site's zone (`timezone`) */
  cancellable_until: string
  /** or null — UTC instant; show in the site's zone (`timezone`) */
  cancelled_at: string | null
  /** when dispatch took it, or null — UTC instant; show in the site's zone (`timezone`) */
  acknowledged_at: string | null
  /** when the control room SENT an officer, or null. The first moment "help is on the way" is true — never say it from `acknowledged_at` — UTC instant; show in the site's zone (`timezone`) */
  dispatched_at: string | null
  /** when an officer was recorded as on the way (from their handset, or by dispatch after a radio call), or null. May stay null for good: an officer who ran straight there has `on_scene_at` only, and nothing is back-filled — draw the step as not recorded, never as done — UTC instant; show in the site's zone (`timezone`) */
  en_route_at: string | null
  /** when an officer was recorded as at the scene, or null — UTC instant; show in the site's zone (`timezone`) */
  on_scene_at: string | null
  /** when the alert was closed — resolved, a false alarm, or cancelled from the phone; `status` says which — or null — UTC instant; show in the site's zone (`timezone`) */
  resolved_at: string | null
  /** the server's time of the alert — UTC instant; show in the site's zone (`timezone`) */
  server_time: string
  /** the handset's time of the press — UTC instant; show in the site's zone (`timezone`) */
  device_time: string
  /** true when the device time is more than two minutes AHEAD of the server's. A device time in the past is an act queued with no signal, not a wrong clock, and is not flagged */
  clock_skewed: boolean
  /** true, always — the control room has this alert from the moment it is recorded, whoever is on shift */
  console_alerted: boolean
  /** how many security HANDSETS the alert was sent to, or null while the fan-out is still running. 0 means none: say so plainly and put the emergency number first. NULL IS NOT 0 */
  alerted_handsets: number | null
  /** which tier answered: `on_duty` (guards clocked on), `rostered` (nobody clocked on, so the officers rostered here today), `escalation` (no handset at all — the site's escalation contact was told off-app) or `none`, or null while it is still running */
  alerted_via: string | null
  /** how many people were told OFF-APP — the site's escalation contacts, e-mailed on EVERY panic whether or not a handset was reached (M10 §1) — or null while it is still running. An email or a console bell, never a phone: it is never "help is coming" and never adds to `alerted_handsets` */
  escalated_contacts: number | null
  /** how many officer PHONES the call-style ring has been sent to so far, in any round — including the ring to every officer of the estate that goes at once when `alerted_handsets` is 0 (M18) — or null while the ring has not begun. Sent, not answered. When `alerted_handsets` is 0 and this is above 0, officers' phones ARE being rung: do not say "no officer's phone was reached" */
  rang_handsets: number | null
  /** when the call-style ring was first sent to a phone (ISO 8601), or null when no round has been sent. The time the resident's "Officers alerted" line is ticked with when the ring is what alerted them (M18A) */
  rang_at: string | null
  /** how many officers were CLOCKED ON at the site when the alert was raised (the raiser not counted), or null on an older alert or while the fan-out is still running. With `alerted_handsets` 0 it tells "nobody is on duty" (0) from "officers are on duty but their phones could not be reached" (above 0). Null: claim neither (M18A §1.2) */
  on_duty_officers: number | null
  /** how many of the site's emergency numbers were ON FILE for this alert, or null while it is still running. NOT how many were texted — never write "N people texted" from it; show `sms.note` */
  sms_recipients: number | null
  /** how many of those texts a PROVIDER ACCEPTED, or null while it is still running. 0 on every alert today — no SMS provider is bought yet, so the message is written down and delivered to nobody. NEVER add this to `alerted_handsets`: a text is not an officer being sent */
  sms_delivered: number | null
  sms: {
    /** true only when an SMS provider can actually send a text right now. false on this platform today: the log driver writes a message down and delivers it to nobody */
    provider_connected: boolean
    /** how many numbers were handed to a REAL provider for this alert. A message written to the log, or a number nobody can dial, is not an attempt */
    attempted: number
    /** how many of those a provider ACCEPTED — the furthest the platform can honestly claim. Never a count of phones that rang */
    delivered: number
    /** true once the texting has run to the end. Until then `attempted` and `delivered` are "so far" */
    finished: boolean
    /** the one sentence to show about texts, e.g. "No text was sent — no SMS provider is connected." Show it as given; never build a claim about texts from the numbers */
    note: string
    /** null on an officer's duress — only a resident's panic texts a household. Otherwise the texts to the resident's own nominated emergency contacts (the first 5 on file), counted by the same rules as the fields above and never included in them */
    household: {
      /** how many of the household's contacts were handed to a REAL provider for this alert. Under the log driver this is 0: the message is written down and delivered to nobody */
      attempted: number
      /** how many of those a provider ACCEPTED — never "received": the carrier and the phone are downstream. Say it only as the provider accepting it */
      delivered: number
      /** true once the household's texting has run to the end, including at once when the household has no contacts on file. Until then `attempted` and `delivered` are "so far" */
      finished: boolean
    } | null
  }
  /** true when this is a DRILL raised to test the fan-out, never by a handset. Show DRILL before anything else on the screen; false on every alert a person raises */
  is_drill: boolean
  /** true when the office had drill mode on for this account when it was pressed: a DRILL (`is_drill` is true too) that rang no officer, emailed and texted nobody and sounded no siren. The counts above stay null for good, so say that instead of waiting on them, and keep the emergency number one press away in case it is real. Absent on a server older than this release */
  drill_mode?: boolean
  messages: {
    /** the message */
    id: number | string
    /** `you` (the resident) or `dispatch` (the control room) */
    from: 'you' | 'dispatch'
    /** the dispatcher's first name on a reply, or null */
    name: string | null
    /** what was written */
    body: string
    /** when the server received it — UTC instant; show in the site's zone (`timezone`) */
    at: string
    /** when the OTHER side was shown it — the console drew it (your message), or this phone read it back (a reply) — or null: "Sent" until then, "Delivered" after — UTC instant; show in the site's zone (`timezone`) */
    seen_at: string | null
    /** on your own messages, the `client_key` the phone sent it with — how the phone matches a message it queued to the row; null on a reply */
    client_key: string
  }[]
  /** the emails a panic sends */
  email: {
    /** null on an officer's duress. Otherwise the emails to the household's own emergency contacts (the first 5) AND its members (M18C: every member with an email of their own, the raiser not included, up to 10), each address once, counted from the ledger */
    household: {
      /** how many people this alert is emailing — contacts and members together; null until the fan-out reaches the leg. 0: nobody has an email address on file (or a simulated/demonstration alert) */
      recipients: number | null
      /** of `sent`, how many were to the household's own members (M18C §4.3) */
      members_sent: string
      /** of `sent`, how many were to its emergency contacts */
      contacts_sent: string
      /** how many the mail server ACCEPTED — never "received". The only number that may put "emailed" on the screen */
      sent: number
      /** how many were refused after every retry, or whose address was gone by the time it was sent */
      failed: number
      /** true once every recipient has an outcome. Until then `sent` is "so far" */
      finished: boolean
    } | null
  }
}

