/** GET /meetings — General and phase meetings, newest first — everything ahead, then the past — with agendas and the household's RSVP. At most 50 an answer, and `next_before` reaches the older ones, so the whole history can be read. Board resident-app-18. */
export type MeetingsIndexRequest = {
  /** optional (query) · the previous answer's `next_before`; leave it out for the newest */
  before?: string
} | void
export type MeetingsIndexResponse = {
  /** send this as `before` for the next older page, or null when nothing is older */
  next_before: string | null
  items: {
    /** the meeting */
    id: number | string
    /** `agm`, `egm` or `phase` */
    type: 'agm' | 'egm' | 'phase'
    /** title */
    title: string
    /** UTC instant; show in the site's zone (`timezone`) */
    starts_at: string
    /** `in_person`, `zoom`, `google_meet`, `teams` or `other` — say the mode by name rather than inferring it from the link */
    held_as: string
    /** or null — the platform by name for an online meeting: "Zoom", "Google Meet", "Microsoft Teams", or for `other` the name the estate typed ("Webex"), else "Other online". Null in person */
    platform: string | null
    /** the one line to show: the venue for an in-person meeting, the mode for an online one, and both when it is hybrid. Composed on the server so the console, the notice and this app cannot word it three ways. */
    place: string
    /** or null — present on an in-person meeting, and on a hybrid one as well */
    venue: string | null
    /** or null — the joining link, http or https only. Null whenever `held_as` is `in_person`, even if one was set before the meeting moved offline. */
    virtual_link: string | null
    /** `scheduled`, `held`, `postponed` or `cancelled` — `held` once a published meeting is more than six hours past its start (M21 §1.4); `postponed` is told, then moved with no new date yet (M56 §2.3) */
    status: string
    /** or null — why it was postponed or cancelled, in the office's words (M56 §1.2) */
    reason: string | null
    /** or null — what the meeting is about */
    description: string | null
    /** boolean — tell the resident before they join */
    recording_enabled: boolean
    agenda: {
      /** HH:MM:SS, or null — a TIME OF DAY on the site's clock, as the office typed it; not an instant, never converted */
      start_time: string | null
      /** item */
      text: string
    }[]
    /** boolean */
    minutes_available: boolean
    /** `attending`, `apologies`, `not_attending` or null */
    my_rsvp: 'attending' | 'apologies' | 'not_attending' | null
  }[]
}

/** GET /meetings/{meeting}/minutes — A meeting's minutes, once the estate office has published them (M21 §1.4) — the text as published, when, and who recorded it. Nothing about who attended. */
