/** GET /amenities — Bookable amenities and their terms, and whether the household may book. Board resident-app-22. */
export type AmenitiesIndexRequest = void
export type AmenitiesIndexResponse = {
  /** false while the household is restricted from bookings */
  may_book: boolean
  /** boolean — a booking can be paid for in the app with a TEST card, which confirms it at once (`bookings.book`, M47 §10); false: a booking is a request the estate approves (`bookings.store`) */
  card_payments: boolean
  items: {
    /** the amenity */
    id: number | string
    /** e.g. "Club House" */
    name: string
    /** icon */
    icon_key: string
    /** guests */
    capacity: string
    /** HH:MM:SS — a TIME OF DAY on the site's clock, not an instant; never converted */
    opens_at: string
    /** HH:MM:SS — a TIME OF DAY on the site's clock (`24:00:00` is the end of the day), not an instant; never converted */
    closes_at: string
    /** decimal string */
    booking_fee: string
    /** decimal string */
    deposit: string
    /** `JMD` */
    currency: string
    /** or null */
    cancellation_hours: number | null
    /** or null */
    booking_window_days: string | null
    /** boolean — a booking of it is a request the estate office approves (`bookings.store`), its fee charged then; it is never paid for in the app, whatever `card_payments` says (M53 §2). False: as `card_payments` says */
    requires_approval: boolean
    taken: {
      /** UTC instant; a period already booked or closed begins — show in the site's zone */
      starts_at: string
      /** UTC instant; and ends */
      ends_at: string
    }[]
    /** or null — "garden setting": what the place is, after its capacity (M47 §8.2) */
    description: string | null
    /** or null — "Phase 2": where it is on the estate (M47 §9.4) */
    place: string | null
    /** decimal string, or null — "$2,000/hr": the fee is this times the hours booked (`bookings.quote` works it out). Null: one flat `booking_fee` per booking */
    hourly_rate: string | null
    /** integer, or null — the blocks the day is booked in, from opening: 120 is "9–11 AM · 11–1 PM · …". Null: one hour */
    slot_minutes: number | null
    /** or null — "noise cut-off at 9:00 PM and no glassware on the lawn", after "I've read and accept the … house rules, including" */
    rules_summary: string | null
    /** or null — the house rules themselves, which the rules link opens */
    rules: string | null
  }[]
}

/** GET /amenities/{amenity}/quote — What booking these hours would cost, worked out by the server (M47 §9.5) — the phone shows the figures and adds none of them up: the fee (the hourly rate times the hours, or the flat fee), anything the household already owes that a payment clears first (payments clear the oldest charge first, D-179), money paid ahead that pays the fee first, the deposit, and the total the card would be charged. */
export type BookingsQuoteRequest = {
  /** path: {amenity} */
  amenity: number | string
  /** required */
  starts_at: string
  /** required · after starts_at */
  ends_at: string
}
export type BookingsQuoteResponse = {
  /** integer — how long, "2 hrs" */
  minutes: number
  /** decimal string, or null for a flat fee — "× $2,000" */
  hourly_rate: string | null
  /** decimal string — "Gazebo rate — 2 hrs × $2,000 … $4,000" */
  fee: string
  /** decimal string — what the household owes from before, cleared first by the payment (0.00 for most) */
  owed_before: string
  /** decimal string — money paid ahead, which pays for the fee first (0.00 for most) */
  credit: string
  /** decimal string — "Refundable damage deposit" */
  deposit: string
  /** decimal string — "Total due today", and what "Confirm & pay" charges */
  total: string
  /** `JMD` */
  currency: string
}

/** POST /bookings/book — Book these hours AND pay for them with one of Stripe's TEST cards — CONFIRMED when it returns (M47 §10, the user's "confirmed on payment"). All or nothing: the booking, the estate's yes, the fee raised and paid with a real (demonstration) receipt, the deposit held, a confirmation code, and the guests' pass for its hours (`gate_token`). A declined card, a refusal, or a total that changed since it was shown makes nothing. The estate's own checks all stand: hours, the diary, the arrears rule. Only while `card_payments`; otherwise a booking is a request (`bookings.store`). */
export type BookingsBookRequest = {
  /** required */
  amenity_id: number
  /** required · in the future, within the booking window */
  starts_at: string
  /** required */
  ends_at: string
  /** required · `visa`, `mastercard`, `amex` or `discover` */
  brand: 'visa' | 'mastercard' | 'amex' | 'discover'
  /** required · the test card's last four digits — never the whole number */
  last4: string
  /** required · the `bookings.quote` total the phone showed — a different one now is refused (409), never taken */
  total: string
  /** true when the house rules box was ticked — required where the amenity has `rules`, and ignored where it has none */
  rules_accepted: boolean
  /** Outbox replays only: the Idempotency-Key and device time the act was captured with. */
  __stamp?: import('../write').WriteStamp
}
export type BookingsBookResponse = {
  /** the booking */
  id: number | string
  /** e.g. `BKG-2026-09-0004` */
  reference: string
  amenity: {
    /** amenity */
    id: number | string
    /** its name */
    name: string
  }
  /** UTC instant; show in the site's zone (`timezone`) */
  starts_at: string
  /** UTC instant; show in the site's zone (`timezone`) */
  ends_at: string
  /** or null */
  guests: string | null
  /** `pending`, `confirmed`, `declined`, `cancelled`, `completed` or `expired` (a request the estate did not decide before its time came: nobody declined it; M53 §2) */
  status: 'pending' | 'confirmed' | 'declined' | 'cancelled' | 'completed' | 'expired'
  /** decimal string */
  booking_fee: string
  /** decimal string */
  deposit: string
  /** `none`, `awaiting`, `held`, `refunded` or `forfeited` (it always moves on: a held deposit is refunded when the booking is cancelled in the app or declined, or three days after it ends with no claim made; the estate may keep all or part of one, with a reason; an unpaid one on a booking that is over becomes none) */
  deposit_state: 'none' | 'awaiting' | 'held' | 'refunded' | 'forfeited'
  /** decimal string, or null — what the estate kept of a forfeited deposit; the rest of the deposit went back to the household */
  deposit_kept: string | null
  /** `JMD` */
  currency: string
  /** the app may cancel until this moment — UTC instant; show in the site's zone (`timezone`) */
  cancellable_until: string
  /** or null */
  declined_reason: string | null
  /** or null — UTC instant; show in the site's zone (`timezone`) */
  cancelled_at: string | null
  /** boolean — the fee has been raised as a charge on the unit */
  fee_charged: boolean
  /** decimal string — what is still owed on the fee (the whole fee when not yet charged; 0.00 with no fee, or on a declined, cancelled or expired booking never charged) */
  fee_outstanding: string
  /** decimal string — what a card payment for the fee takes: the fee and every older charge still owing, since payments clear the oldest charge first (0.00 when nothing is owed on the fee) */
  fee_to_clear: string
  /** boolean — a fee was charged and nothing is owed on it */
  fee_paid: boolean
  /** boolean — a TEST card paid the deposit (M12 §2.6): held, refunded or kept like any, and no money moved */
  deposit_demonstration: boolean
  /** or null — "GZ-2609-A4" (M47 §10): a booking paid for in the app (`bookings.book`), confirmed at once; a short code a guard can read aloud */
  confirmation_code: string | null
  /** or null — the guests' pass for the booking's hours, signed like any visitor pass: draw it as the QR. Only while the booking is confirmed and still to come */
  gate_token: string | null
  /** or null — "Visa •••• 4417": the (test) card it was paid with, where the deposit goes back to. Never more than the brand and last four */
  paid_with: string | null
  /** the fee's receipt, or null when nothing was owed on it */
  receipt: {
    /** the payment — `/payments/{payment}/receipt` shows it */
    id: number | string
    /** e.g. `PPV-R-04471` */
    receipt_no: string
    /** decimal string */
    amount: string
    /** e.g. "Demonstration card payment · Visa •••• 4242" */
    reference: string
    /** always true */
    is_demonstration: string
  } | null
  /** the server's time — UTC instant; show in the site's zone (`timezone`) */
  server_time: string
  /** the handset's time, as sent in X-Device-Time — UTC instant; show in the site's zone (`timezone`) */
  device_time: string
  /** true when the device time is more than two minutes AHEAD of the server's. A device time in the past is an act queued with no signal, not a wrong clock, and is not flagged */
  clock_skewed: boolean
}

